import java.io.BufferedInputStream

private const val MOD = 1_000_000_007L

private fun powMod(base: Long, exponent: Long): Long {
    if (exponent == 0L) return 1L
    if (exponent % 2L == 0L) {
        val value = base * base % MOD
        return powMod(value, exponent / 2L)
    }
    return base * powMod(base, exponent - 1L) % MOD
}

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result * sign
    }
}

fun main() {
    val scanner = FastScanner()
    val k = scanner.nextInt()
    val va = scanner.nextInt()
    val vb = scanner.nextInt()

    val denominatorInverse = powMod((va.toLong() + vb) % MOD, MOD - 2)
    val pa = va.toLong() * denominatorInverse % MOD
    val pb = vb.toLong() * denominatorInverse % MOD
    val oneB = pa * powMod(pb, MOD - 2) % MOD

    val dp = Array(k + 1) { LongArray(k + 2) }

    for (i in k - 1 downTo 0) {
        for (j in k downTo 1) {
            dp[i][j] = if (i + j >= k) {
                (i.toLong() + j + oneB) % MOD
            } else {
                (pa * dp[i][j + 1] + pb * dp[i + j][j]) % MOD
            }
        }
    }

    println(dp[0][1])
}

